        }
        if(dup2(0, newfd) < 0) {
                err("dup2 stdin");
        }
        if(dup2(1, newfd) < 0) {
                err("dup2 stdout");
        }
        if(dup2(2, newfd) < 0) {
                err("dup2 stderr");
