/*
 * Tree files support.
 *
 * When an export is configured with the treefiles option, the exported
 * block device is stored as a tree of small block files below the
 * directory named by the export. Each block file holds TREEPAGESIZE
 * bytes of data; every directory holds at most TREEDIRSIZE files or
 * subdirectories, so an export of any size can be represented by
 * choosing a deep enough nesting level.
 *
 * The block containing the byte at offset pos in the device is the
 * block number pos / TREEPAGESIZE. That number is written in base
 * TREEDIRSIZE with exactly as many digits as the tree is deep; every
 * digit but the last one names a subdirectory (TREEXXXX), the last one
 * names the block file itself (FILEXXXX).
 */

#include "lfs.h"
#include "treefiles.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

/* longest path we can represent; comfortably larger than PATH_MAX on
 * any system we care about */
#define TREE_PATHLEN 4096

/**
 * Compute the depth of the tree needed to store a device of the given
 * size. The depth is the number of path components below the export
 * directory, i.e. a depth of 1 means the block files live in the
 * export directory itself.
 *
 * @param size the total size of the exported device
 * @return the depth of the tree
 **/
static int tree_depth(off_t size) {
	off_t blocks;
	off_t capacity;
	int depth;

	blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	depth = 1;
	capacity = TREEDIRSIZE;
	while (capacity < blocks && depth < 10) {
		capacity *= TREEDIRSIZE;
		depth++;
	}

	return depth;
}

/**
 * Construct the path of the block file holding the data at position
 * pos of a device of the given size, appending it to the name of the
 * export directory.
 *
 * @param name name of the export directory on entry; on return, the
 * full path of the block file. Must be a buffer of at least lenmax
 * bytes.
 * @param lenmax size of the name buffer
 * @param size total size of the exported device
 * @param pos offset into the device
 * @param ppos [out] offset into the device at which the block file
 * starts
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block;
	off_t divisor;
	int depth;
	int level;
	int used;

	block = pos / TREEPAGESIZE;
	depth = tree_depth(size);
	if (ppos) {
		*ppos = block * TREEPAGESIZE;
	}

	used = strlen(name);
	for (level = depth - 1; level >= 0; level--) {
		int digit;
		int written;

		divisor = 1;
		for (int i = 0; i < level; i++) {
			divisor *= TREEDIRSIZE;
		}
		digit = (block / divisor) % TREEDIRSIZE;
		written = snprintf(name + used, lenmax - used,
				level > 0 ? "/TREE%04d" : "/FILE%04d", digit);
		if (written < 0 || written >= lenmax - used) {
			/* path truncated; make sure we fail loudly */
			name[lenmax - 1] = '\0';
			errno = ENAMETOOLONG;
			return;
		}
		used += written;
	}
}

/**
 * Create the directory given by path, along with all its parent
 * directories. Existing directories are silently accepted.
 *
 * @param path the directory to create
 **/
void mkdir_path(char *path) {
	char *p;

	for (p = path + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			mkdir(path, 0700);
			*p = '/';
		}
	}
	mkdir(path, 0700);
}

/**
 * Open the block file holding the data at position pos of a device of
 * the given size, creating it (and any directories needed to reach it)
 * if the mode allows for creation.
 *
 * @param name name of the export directory
 * @param mode open(2) flags; pass O_CREAT to allow file creation
 * @param size total size of the exported device
 * @param pos offset into the device
 * @param mutex serializes path construction and directory creation
 * @return a file descriptor open to the block file, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[TREE_PATHLEN];
	char *slash;
	int fd;

	pthread_mutex_lock(mutex);
	strncpy(path, name, sizeof(path));
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, NULL);

	/* create the directories leading to the block file; reading a
	 * device that was never written must not create anything */
	if (mode & O_CREAT) {
		slash = strrchr(path, '/');
		if (slash != NULL) {
			*slash = '\0';
			mkdir_path(path);
			*slash = '/';
		}
	}

	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);

	return fd;
}

/**
 * Delete the block file holding the data at position pos of a device
 * of the given size, if it exists. Used when a block is marked as
 * unused.
 *
 * @param name name of the export directory
 * @param size total size of the exported device
 * @param pos offset into the device
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[TREE_PATHLEN];

	strncpy(path, name, sizeof(path));
	path[sizeof(path) - 1] = '\0';
	construct_path(path, sizeof(path), size, pos, NULL);
	if (unlink(path) < 0 && errno != ENOENT) {
		DEBUG("could not delete tree file %s: %s", path, strerror(errno));
	}
}

