/**
 * Read an amount of bytes at a given offset from a treefiles export.
 * Reads never span more than one block file, and reading a block that
 * was never written returns zeroes.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error.
 **/
static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t blockend;
	ssize_t retval;
	int fhandle;

	blockend = (a / TREEPAGESIZE + 1) * TREEPAGESIZE;
	if (blockend > (off_t)client->exportsize)
		blockend = client->exportsize;
	if (len > (size_t)(blockend - a))
		len = blockend - a;

	fhandle = open_treefile(client->exportname, O_RDONLY,
			client->exportsize, a, &client->treefiles_lock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			/* the block was never written; it reads as zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	DEBUG("(READ from tree file fd %d offset %llu len %u), ", fhandle,
	      (long long unsigned int)(a % TREEPAGESIZE), (unsigned int)len);
	retval = pread(fhandle, buf, len, a % TREEPAGESIZE);
	close(fhandle);
	return retval;
}
```

